import{_ as r,a0 as s,w as o,s as h,ao as d,I as i,x as a,a1 as t,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"FISH：Linux 的一个智能易用的 Shell | LCTT x X-CMD","titleTemplate":false,"description":"FISH：Linux 的一个智能易用的 Shell | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"FISH：Linux 的一个智能易用的 Shell | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"FISH：Linux 的一个智能易用的 Shell | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150906 FISH--A smart and user-friendly command line shell for Linux","title":"FISH：Linux 的一个智能易用的 Shell","tag":"201509","desc":""},"relativePath":"201509/20150906 FISH--A smart and user-friendly command line shell for Linux.md","filePath":"[post].md"}'),u={name:"201509/20150906 FISH--A smart and user-friendly command line shell for Linux.md"};function p(f,e,m,x,b,S){const l=s("Link");return o(),h("div",null,[e[16]||(e[16]=d(`<h1 id="fish-linux-的一个智能易用的-shell" tabindex="-1">FISH：Linux 的一个智能易用的 Shell <a class="header-anchor" href="#fish-linux-的一个智能易用的-shell" aria-label="Permalink to “FISH：Linux 的一个智能易用的 Shell”">​</a></h1><p>FISH（friendly interactive shell）是一个用户友好的命令行 shell，主要是用来进行交互式使用。shell 就是一个用来执行其他程序的程序。</p><h3 id="fish-特性" tabindex="-1">FISH 特性 <a class="header-anchor" href="#fish-特性" aria-label="Permalink to “FISH 特性”">​</a></h3><h4 id="自动建议" tabindex="-1">自动建议 <a class="header-anchor" href="#自动建议" aria-label="Permalink to “自动建议”">​</a></h4><p>fish 会根据你的历史输入和补完来提供命令建议，就像一个网络浏览器一样。注意了，就是Netscape Navigator 4.0!</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Fish-Auto-Suggestion.gif" alt=""></p><h4 id="漂亮的vga-色彩" tabindex="-1">漂亮的VGA 色彩 <a class="header-anchor" href="#漂亮的vga-色彩" aria-label="Permalink to “漂亮的VGA 色彩”">​</a></h4><p>fish 原生支持 term256， 它就是一个终端技术的艺术国度。 你将可以拥有一个难以置信的、256 色的shell 来使用。</p><h4 id="理智的脚本" tabindex="-1">理智的脚本 <a class="header-anchor" href="#理智的脚本" aria-label="Permalink to “理智的脚本”">​</a></h4><p>fish 是完全可以通过脚本控制的，而且它的语法又是那么的简单、干净，而且一致。你甚至不需要去重写。</p><h4 id="基于-web-的配置" tabindex="-1">基于 web 的配置 <a class="header-anchor" href="#基于-web-的配置" aria-label="Permalink to “基于 web 的配置”">​</a></h4><p>对于少数能使用图形计算机的幸运儿， 你们可以在网页上配置你们自己的色彩方案，以及查看函数、变量和历史记录。</p><h4 id="帮助手册补全" tabindex="-1">帮助手册补全 <a class="header-anchor" href="#帮助手册补全" aria-label="Permalink to “帮助手册补全”">​</a></h4><p>其它的 shell 支持可配置的补全， 但是只有 fish 可以通过自动转换你安装好的 man 手册来实现补全功能。</p><h4 id="开箱即用" tabindex="-1">开箱即用 <a class="header-anchor" href="#开箱即用" aria-label="Permalink to “开箱即用”">​</a></h4><p>fish 将会通过 tab 补全和语法高亮使你非常愉快的使用shell， 同时不需要太多的学习或者配置。</p><h3 id="在ubuntu-15-04-上安装fish" tabindex="-1">在ubuntu 15.04 上安装FISH <a class="header-anchor" href="#在ubuntu-15-04-上安装fish" aria-label="Permalink to “在ubuntu 15.04 上安装FISH”">​</a></h3><p>打开终端，运行下列命令：</p><pre><code>sudo apt-add-repository ppa:fish-shell/release-2
sudo apt-get update
sudo apt-get install fish
</code></pre><p>###使用FISH###</p><p>打开终端，运行下列命令来启动FISH：</p><pre><code>fish
</code></pre><p>欢迎来到 fish，友好的交互式shell，输入指令 help 来了解怎么使用fish。</p>`,23)),i("p",null,[e[1]||(e[1]=a("阅读",-1)),t(l,{href:"http://fishshell.com/docs/current/index.html#introduction"},{default:n(()=>[...e[0]||(e[0]=[a("FISH 文档",-1)])]),_:1}),e[2]||(e[2]=a(" ，掌握使用方法。",-1))]),e[17]||(e[17]=i("hr",null,null,-1)),i("p",null,[e[4]||(e[4]=a("via: ",-1)),t(l,{href:"http://www.ubuntugeek.com/fish-a-smart-and-user-friendly-command-line-shell-for-linux.html"},{default:n(()=>[...e[3]||(e[3]=[a("http://www.ubuntugeek.com/fish-a-smart-and-user-friendly-command-line-shell-for-linux.html",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=a("作者：",-1)),t(l,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:n(()=>[...e[5]||(e[5]=[a("ruchi",-1)])]),_:1}),e[9]||(e[9]=a(" 译者：",-1)),t(l,{href:"https://github.com/oska874"},{default:n(()=>[...e[6]||(e[6]=[a("oska874",-1)])]),_:1}),e[10]||(e[10]=a(" 校对：",-1)),t(l,{href:"https://github.com/wxy"},{default:n(()=>[...e[7]||(e[7]=[a("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=a("本文由 ",-1)),t(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[11]||(e[11]=[a("LCTT",-1)])]),_:1}),e[14]||(e[14]=a(" 原创编译，",-1)),t(l,{href:"https://linux.cn/"},{default:n(()=>[...e[12]||(e[12]=[a("Linux中国",-1)])]),_:1}),e[15]||(e[15]=a(" 荣誉推出",-1))])])}const F=r(u,[["render",p]]);export{w as __pageData,F as default};
